#!/usr/bin/python3
"""Safely and transactionally unpack one supplier tar archive."""

import os
import shutil
import sys
import tarfile
import tempfile


def fail(message):
    raise ValueError(message)


def validate_member(member):
    name = member.name
    if not name or "\x00" in name:
        fail("empty or invalid member name")
    if name.startswith("/"):
        fail("absolute member path: %r" % name)
    if ".." in name.split("/"):
        fail("parent traversal in member path: %r" % name)

    if member.issym() or member.islnk():
        target = member.linkname
        if not target or "\x00" in target or target.startswith("/"):
            fail("unsafe link target for %r: %r" % (name, target))
        if member.issym():
            target = os.path.join(os.path.dirname(name), target)
        normalized = os.path.normpath(target)
        if normalized == ".." or normalized.startswith("../"):
            fail("link escapes destination for %r: %r" % (name, member.linkname))

    if member.ischr() or member.isblk() or member.isfifo():
        fail("special-file member is not permitted: %r" % name)


def main():
    if len(sys.argv) != 2:
        print("usage: unpack ARCHIVE", file=sys.stderr)
        return 2

    base = os.path.realpath(os.path.join(os.path.dirname(__file__), ".."))
    destination = os.path.join(base, "incoming")
    stage = tempfile.mkdtemp(prefix=".incoming-stage-", dir=base)
    backup = None

    try:
        if os.path.lexists(destination):
            if os.path.islink(destination) or not os.path.isdir(destination):
                fail("incoming must be a real directory")
            shutil.copytree(destination, stage, symlinks=True, dirs_exist_ok=True)

        with tarfile.open(sys.argv[1], mode="r:*") as archive:
            members = archive.getmembers()
            for member in members:
                validate_member(member)
            archive.extractall(stage, members=members, filter="data")

        if os.path.lexists(destination):
            backup = tempfile.mkdtemp(prefix=".incoming-old-", dir=base)
            os.rmdir(backup)
            os.rename(destination, backup)

        try:
            os.rename(stage, destination)
            stage = None
        except BaseException:
            if backup is not None and not os.path.lexists(destination):
                os.rename(backup, destination)
                backup = None
            raise

        if backup is not None:
            shutil.rmtree(backup)
            backup = None
        return 0
    except (OSError, tarfile.TarError, ValueError) as exc:
        print("unpack: rejected archive: %s" % exc, file=sys.stderr)
        return 1
    finally:
        if stage is not None:
            shutil.rmtree(stage, ignore_errors=True)
        if backup is not None and os.path.lexists(backup):
            if not os.path.lexists(destination):
                os.rename(backup, destination)
            else:
                shutil.rmtree(backup, ignore_errors=True)


if __name__ == "__main__":
    sys.exit(main())
